export type PolicyBrand = { name: string; registrationNumber?: string | null; address?: string | null; email?: string | null; phone?: string | null; website?: string | null; primaryColour?: string | null; footerText?: string | null };
export type GeneratedPolicySection = { heading: string; paragraphs: string[] };

