export function sourceAnnex(template: PolicyTemplate): PolicySource[] {
  const keys = [...template.sourceKeys];
  if (["Workforce", "Recruitment", "Whistleblowing", "Equality and diversity"].includes(template.category)) keys.push("employment-rights", "equality-act", "gov-employing");
  if (template.key === "dbs-right-work" || template.key === "safer-recruitment") keys.push("right-to-work", "dbs-employers");
  if (template.key === "absence-wellbeing") keys.push("working-time", "acas-leave", "acas-adjustments");
  return [...new Set(keys)].map((key) => POLICY_SOURCES[key]).filter(Boolean);
}
export function policyTemplate(key: string) { return POLICY_CATALOGUE.find((item) => item.key === key); }

export function generatePolicySections(template: PolicyTemplate, brand: PolicyBrand): GeneratedPolicySection[] {
  const name = brand.name.trim() || "the provider";
  const sources = sourceAnnex(template).map((item) => `${item.publisher}: ${item.title}`).join("; ");
  const employmentRelated = ["Workforce", "Recruitment", "Whistleblowing", "Equality and diversity"].includes(template.category);
  return [
    { heading: "Policy statement", paragraphs: [`${name} is committed ${template.purpose}. This controlled policy sets the minimum organisational standard. It must be read with the person's care plan, local safeguarding and emergency arrangements, employment obligations and any current professional instruction that applies to the situation.`, `This template is CQC-aligned and source-grounded, but adoption does not by itself demonstrate compliance. ${name} must confirm that the document reflects its regulated activities, service model, contracts, local authority pathways, staffing and actual practice before approval.`] },
    { heading: "Purpose and intended outcomes", paragraphs: [`The purpose of this policy is ${template.purpose}. The intended outcome is safe, lawful, person-centred practice that can be evidenced through consistent records, competent decisions and timely improvement.`, `The policy supports the CQC ${template.cqcKey} key question and the following compliance areas: ${template.complianceAreas.join(", ")}. Regulatory references are described in the source annex and must be checked again whenever this policy is reviewed.`] },
    { heading: "Scope", paragraphs: [`This policy applies to directors, registered persons, managers, employees, agency workers, contractors, volunteers and any other person acting on behalf of ${name}. It applies across every location and to remote or community work where the organisation controls or influences the activity.`, `Nothing in this policy authorises a worker to act outside their competence, professional scope, delegated authority or the person's consent. Where law, current clinical instruction or local multi-agency procedure sets a higher or more specific standard, that standard must be followed and the manager informed.`] },
    { heading: "Rights and decision-making", paragraphs: [`Practice must preserve dignity, privacy, equality, autonomy and the person's right to be involved. Information must be communicated in an accessible way, consent must be sought where required, and decision-specific mental capacity principles must be applied whenever there is reason to doubt capacity.`, `Safety measures must be proportionate and must not become blanket restrictions. The person's wishes, strengths, culture, relationships and desired outcomes must be considered alongside foreseeable risk, with advocacy or authorised representatives involved where appropriate.`] },
    { heading: "Regulatory and legal basis", paragraphs: [`This policy is grounded in ${template.complianceAreas.join(", ")}. Its controlled source annex identifies the legislation, CQC requirements and official sector guidance used when the template was prepared. The policy owner must resolve any conflict in favour of current law and must obtain competent advice where interpretation affects a person's rights, safety or employment.`, employmentRelated ? `Because this policy affects workers, ${name} must also apply current employment contracts, collective or recognition arrangements, statutory employment rights, equality duties, data protection, working-time and health-and-safety obligations. A fair procedure in this document must not be treated as legal advice for an individual employment case; material dismissal, immigration, discrimination, transfer or contractual-change decisions require suitably qualified HR or legal review.` : `CQC alignment describes how this document supports regulated care governance; it does not predict or guarantee an inspection judgement. Compliance depends on implementation, competent practice, accurate records, oversight and evidence that learning improves outcomes.`] },
    { heading: "Responsibilities", paragraphs: [`The registered provider remains accountable for adequate resources, oversight and a culture in which concerns are acted on. The Registered Manager is responsible for implementing this policy, confirming local procedures, assigning competent leads and reporting material gaps through governance.`, `Line managers are responsible for briefing workers, checking competence, supervising practice, reviewing records and escalating concerns. Every worker is responsible for following the current approved version, recording contemporaneously, reporting changes and stopping or seeking advice when safe practice cannot be assured.`] },
    { heading: "Procedure", paragraphs: template.practice },
    { heading: "Records and evidence", paragraphs: [`The organisation will maintain ${template.evidence}. Records must be factual, attributable, dated, secure, proportionate and available to authorised reviewers. Corrections must preserve the original entry and explain who changed it, when and why.`, `Records will be retained and disposed of under the approved retention schedule. Access, sharing and confidentiality will follow the organisation's information governance controls, while safeguarding, statutory reporting and legal-preservation duties will take precedence where applicable.`] },
    { heading: "Training, competence and supervision", paragraphs: [`Workers will receive role-appropriate induction, training, supervised practice and competence assessment before undertaking duties covered by this policy without support. Managers will determine refresher frequency from law, guidance, role, incidents, audit and individual need rather than relying only on certificate expiry.`, `Supervision will create space to examine judgement, values, workload, concerns and learning. A worker who is not competent or whose practice creates risk will receive immediate protection measures, support and reassessment, with duties restricted where necessary.`] },
    { heading: "Monitoring and improvement", paragraphs: [`${name} will monitor this policy through audits, record sampling, incident and complaint themes, feedback from people and workers, supervision, outcome measures and governance review. Findings will lead to named actions with deadlines, evidence and measures of success.`, `Leaders will test whether improvement is embedded and beneficial. Serious, repeated or systemic gaps will be placed on the risk register and escalated to the registered provider, commissioners, safeguarding partners, CQC or another authority where required.`] },
    { heading: "Review and approval", paragraphs: [`This policy is a draft until approved through ${name}'s governance process. It must be reviewed at least annually and sooner after relevant legal or guidance change, a serious incident, service-model change, audit finding or evidence that the procedure is not achieving its intended outcome.`, `The source annex was last checked on ${CHECKED} and currently includes ${sources}. The policy owner must verify that every link and requirement remains current before approval and must record local customisations, consultation, implementation arrangements and the next review date.`] },
  ];
}

export function policyBrandFromOrganisation(organisation: { name: string; policyBrandName: string | null; policyRegistrationNumber: string | null; policyAddress: string | null; policyEmail: string | null; policyPhone: string | null; policyWebsite: string | null; policyPrimaryColour: string; policyFooterText: string | null }): PolicyBrand {
  return { name: organisation.policyBrandName || organisation.name, registrationNumber: organisation.policyRegistrationNumber, address: organisation.policyAddress, email: organisation.policyEmail, phone: organisation.policyPhone, website: organisation.policyWebsite, primaryColour: organisation.policyPrimaryColour, footerText: organisation.policyFooterText };
}
